#!/usr/bin/env python3
"""crispr/off_target_predict — auto-generated run.py (archetype=crispr).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "crispr"
BRAIN = "crispr"
SKILL = "off_target_predict"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'off_target_predict', 'n_guides': 0, 'guides_csv': '', 'best_guide': {'seq': '', 'cfd_score': 0.0, 'mit_score': 0.0}, 'diagnostics': {'brain': 'crispr', 'archetype': 'crispr'}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """cas-offinder off-target 预测。host_env=PRAXIS-CRISPR-bins。"""
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401
    guides = payload.get("guide_sequences") or ([payload.get("guide_sequence")] if payload.get("guide_sequence") else [])
    genome_fa = payload.get("genome_fa") or payload.get("genome_path")
    pam = payload.get("pam", "NGG")
    mismatches = int(payload.get("mismatches", 3))
    out_dir = payload.get("out_dir") or _tempfile.mkdtemp(prefix="casoff_")
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "tool": "cas-offinder", "n_guides": len(guides), "out_dir": out_dir}
    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL, "n_guides": 0, "guides_csv": "",
                "best_guide": {"seq": "", "cfd_score": 0.0, "mit_score": 0.0},
                "diagnostics": {**diagnostics, "dry": True}}
    if not guides or not genome_fa or not _os.path.isfile(genome_fa):
        return {"ok": False, "error": "需要 guide_sequence(s) + genome_fa", "diagnostics": diagnostics}
    in_txt = _os.path.join(out_dir, "input.txt")
    out_txt = _os.path.join(out_dir, "offtargets.txt")
    _os.makedirs(out_dir, exist_ok=True)
    # cas-offinder format
    lines = [genome_fa, f"NNNNNNNNNNNNNNNNNNNN{pam}".replace("PAM", pam)]
    for g in guides:
        lines.append(f"{g.upper()}NNN {mismatches}")
    with open(in_txt, "w") as fh: fh.write("\n".join(lines))
    t0 = _time.time()
    r = run_tool(["cas-offinder", in_txt, "C", out_txt],
                 timeout=int(payload.get("timeout_s", 3600)))
    diagnostics["subprocess"] = {"wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "cas-offinder 失败"),
                "stderr": r.get("stderr", "")[-400:], "diagnostics": diagnostics}
    n_off = 0
    if _os.path.isfile(out_txt):
        with open(out_txt) as fh: n_off = sum(1 for _ in fh)
    return {"ok": True, "skill_id": SKILL, "n_guides": len(guides),
            "guides_csv": out_txt, "best_guide": {"seq": guides[0], "cfd_score": 0.0, "mit_score": 0.0},
            "n_off_targets": n_off,
            "runtime_sec": round(_time.time() - t0, 2),
            "diagnostics": {**diagnostics, "offtargets_file": out_txt}}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
